using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps;using MapSharedProps.EditorTools;
public static class Lantern174Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static string Out=>Path.Combine(Root,"Evidence174");static void Check(bool b,string m){if(!b)throw new Exception(m);}
 public static void Run(){Directory.CreateDirectory(Out);try{
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var input=Path.Combine(Root,"Input164");var d=SmallPropsV1.Read(Path.Combine(input,"small_props.json"));var root=new GameObject("壁灯更新");var p=new Dictionary<string,GameObject>();MineLanternV1.Build(input,"Assets/Imported164-valid",root.transform,p,d);AssetDatabase.SaveAssets();AssetDatabase.ImportAsset("Assets/Imported164-valid/mine-lantern-shared.mat",ImportAssetOptions.ForceSynchronousImport);Check(p["mine_wall_lantern"].GetComponent<Renderer>().sharedMaterial.IsKeywordEnabled("_EMISSION"),"emission keyword survives material import");UnityEngine.Object.DestroyImmediate(root);
  Lantern164Checks.Out=Out;Lantern164Checks.Load();
  // 正規カタログ変更でも外観を残し、必要時だけColliderを作る。
  var catalog=new List<string>();foreach(string tag in new[]{"nonSolid","circle","shape"}){d=SmallPropsV1.Read(Path.Combine(input,"small_props.json"));var a=d.mineLanternV1.assets[0];if(tag!="nonSolid"){a.radius=.2f;a.height=.7f;a.shape=tag=="shape";a.circleColliders=new[]{new SmallPropsV1.CircleProxy{center=new[]{0f,0f,0f},radius=.2f,height=.7f}};}Check(MineLanternV1.Optional(d.mineLanternV1)!=null,"custom accepted");string folder="Assets/Imported165-"+tag;if(!AssetDatabase.IsValidFolder(folder))AssetDatabase.CreateFolder("Assets","Imported165-"+tag);root=new GameObject(tag);p=new Dictionary<string,GameObject>();MineLanternV1.Build(input,folder,root.transform,p,d);var prefab=p["mine_wall_lantern"];var instance=(GameObject)PrefabUtility.InstantiatePrefab(prefab);Check(instance.GetComponentsInChildren<Renderer>().Length==2,"visual survives "+tag);var c=instance.GetComponent<MeshCollider>();if(tag=="nonSolid")Check(!c,"no collider");else if(tag=="shape")Check(c.sharedMesh==instance.GetComponent<MeshFilter>().sharedMesh,"visual shape collider");else Check(Vector3.Distance(c.sharedMesh.bounds.size,new Vector3(.4f,.7f,.4f))<1e-5,"radius height actual mesh");UnityEngine.Object.DestroyImmediate(instance);UnityEngine.Object.DestroyImmediate(root);catalog.Add(tag);}
  // 不正追加データを含む正常ライブラリから既存51種を実生成する。
  string bad=Path.Combine(Root,"Input165-invalid");Directory.CreateDirectory(bad);File.WriteAllText(Path.Combine(bad,"small_props.json"),File.ReadAllText(Path.Combine(input,"small_props.json")).Replace("\"mineLanternV1\":{\"version\":1","\"mineLanternV1\":{\"version\":999"));Check(SmallPropsV1.Read(Path.Combine(bad,"small_props.json")).mineLanternV1==null,"bad version rejected");File.Copy(Path.Combine(input,"props.csv"),Path.Combine(bad,"props.csv"),true);string badFolder="Assets/Imported165-invalid";if(!AssetDatabase.IsValidFolder(badFolder))AssetDatabase.CreateFolder("Assets","Imported165-invalid");root=new GameObject("fallback");p=new Dictionary<string,GameObject>();SmallPropsV1.Build(bad,badFolder,root.transform,Shader.Find("MapSharedProps/Lit"),p);Check(p.Count==51&&!p.ContainsKey("mine_wall_lantern"),"invalid optional generates existing51");UnityEngine.Object.DestroyImmediate(root);GC.Collect();
  // 新壁灯・旧壁掛け松明・地置き松明・洞窟装飾の正式混在取り込み。
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var full=MapSharedPropsBuilder.Build(Path.Combine(Root,"Input165-mixed"));var budgets=full.root.GetComponentsInChildren<RoomTorchBudget>();Check(budgets.Length==1,"one ordinary light budget across formal routes");var budget=budgets[0];Check(budget.Fixtures.Length==9&&budget.Fixtures.Count(f=>f.IsPooledLamp)==1,"one lamp + eight legacy fixtures");budget.TimeOverride=1;for(int i=0;i<60;i++)budget.Tick(1/30f,new Vector3(12,1.65f,12));Check(budget.ActiveLights<=6&&budget.PooledLampLightCount<=2,"shared total and shadow pool bounded");Check(full.prefabs.Count==72&&full.prefabs.Keys.Count(k=>k.StartsWith("cnd"))==20,"full72 including existing20 cave objects");
  string saved="Assets/Imported164-valid/mixed.prefab";var asset=PrefabUtility.SaveAsPrefabAsset(full.root,saved);UnityEngine.Object.DestroyImmediate(full.root);root=(GameObject)PrefabUtility.InstantiatePrefab(asset);budgets=root.GetComponentsInChildren<RoomTorchBudget>();Check(budgets.Length==1&&budgets[0].Fixtures.Length==9,"mixed budget persists");for(int i=0;i<60;i++)budgets[0].Tick(1/30f,new Vector3(12,1.65f,12));Check(budgets[0].ActiveLights<=6&&budgets[0].ActiveLights>0,"mixed restored lighting");UnityEngine.Object.DestroyImmediate(root);
  var errors=ShaderUtil.GetShaderMessages(Shader.Find("MapTunnels/Tunnel")).Where(m=>m.severity==UnityEditor.Rendering.ShaderCompilerMessageSeverity.Error).ToArray();Check(errors.Length==0,"tunnel shader compile");
  File.WriteAllText(Path.Combine(Out,"checks.json"),"{\"pass\":true,\"emissionSurvivesSaveImport\":true,\"customColliderCases\":[\"nonSolid\",\"circle\",\"shape\"],\"invalidOptionalOld51Generated\":true,\"formal72\":true,\"caveDecor20\":true,\"mixedFixtures\":9,\"ordinaryBudgetCount\":1,\"maxOrdinaryLights\":6,\"maxShadowedNewLamps\":2,\"mixedSaveReinstantiate\":true,\"shaderCompileErrors\":0,\"player\":false}");AssetDatabase.SaveAssets();EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Path.Combine(Out,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
